'use strict';
// Neon Harbor: 100 authored rescues in 10 connected chapters, building to why the last ferry never docked.
// Same fields as story-desert.js.
(globalThis.RescueStories=globalThis.RescueStories||[])[2]={chapters:[
{title:'The Tide Board',arc:'The night fishing crews at Pier One were unloading when the harbor locked down. The tide board still promised a ferry that never came.',levels:[
{n:'Haruto',r:'night fisherman',t:'The smoking hold',s:'Haruto, a night fisherman, got his crew off the boat when the engine room started smoking, and is waiting at the end of Pier One.',k:'has been watching the tide board all night',l:'Thirty years of night catches. Tonight the catch was my crew, all of them.',x:'The tide board above the pier still says “LAST FERRY: ARRIVING.” It has said that for six hours.',j:'Six hours arriving.',m:'Mom took that ferry every Friday.',h:'smoke'},
{n:'Lin',r:'net mender',t:'The fallen lamp line',s:'Lin mends nets on Pier One. A neon sign’s power line fell across the boards between her bench and the street.',k:'saw the ferry’s lights in the fog',l:'I fix holes in nets. I can’t fix a live wire, so I didn’t touch it.',x:'Around midnight I saw the ferry’s green light in the fog, close. Then it turned away.',j:'It came close and turned away?',m:'Ferries don’t turn away.',h:'cable'},
{n:'Duc',r:'ice-plant worker',t:'Over the boards',s:'Duc works the pier’s ice plant. Storm surge is washing over the low end of the pier, so he moved up to the loading dock.',k:'knows what the ferry crew bought before leaving',l:'The sea came up the pier like it owned it. Tonight it did.',x:'The ferry’s cook bought two bags of ice from me before the trip. Said, “Might need it for a long night.”',j:'They planned for a long night.',m:'Or someone did.',h:'tide'},
{n:'Ifeoma',r:'fish auctioneer',t:'The early auction',s:'Ifeoma got a message saying the fish auction had moved to East Wharf. She checked with the harbor office first and stayed at Pier One.',k:'traced the fake auction message',l:'The auction hasn’t moved in forty years. A text wasn’t going to move it.',x:'The fake message came from the same number that told the ferry it couldn’t dock.',j:'Someone told the ferry not to dock?',m:'Then the ferry didn’t fail. It was turned away.',h:'radio'},
{n:'Takeshi',r:'harbor clerk',t:'The berth system',s:'Takeshi, the night harbor clerk, refused to read the berth-control password to a caller claiming to be the port authority.',k:'saw the ferry’s berth record',l:'If I give out that password, every boat in the harbor is at risk.',x:'The berth record shows the ferry asked to dock at the clinic side. Someone denied it.',j:'The clinic side.',m:'Why would a ferry need the clinic?',h:'code'},
{n:'Teuila',r:'medic',t:'The pier first-aid kit',s:'Teuila, the pier’s first-aider, sealed the fishermen’s burn and cut kit for the clinic’s night shift.',k:'heard the ferry call for a doctor',l:'Fish hooks, rope burns, sea cold. I’ve seen it all. This kit goes to people who can use it.',x:'On channel sixteen the ferry asked: “Is there a doctor at the clinic tonight?” Nobody answered.',j:'Nobody answered.',m:'We answer now.',h:'medicine',sup:1},
{n:'Bao',r:'student',t:'The bait bucket',s:'Bao, 9, saw his bait bucket wash off the pier. He stayed behind the rail and called his uncle instead of reaching for it.',k:'heard the ferry horn tonight',l:'The bucket floats. I don’t. Uncle says that’s a good reason.',x:'The ferry horn went three short blasts. Uncle says that means “I am going backwards.”',j:'Backwards. Away from the dock.',m:'On purpose.',h:'gate'},
{n:'Moana',r:'boat pilot',t:'The breakwater',s:'Moana could have run her pilot boat through the gap in the breakwater. She waited at the mooring for the surge to drop.',k:'saw where the ferry went',l:'I pilot ships through this harbor every night. Tonight the harbor said wait.',x:'The ferry’s wake went east, toward the clinic side of the bay. Slow and steady.',j:'East. The clinic.',m:'They were going to the clinic.',h:'tide'},
{n:'Sione',r:'deckhand',t:'The red bollard',s:'Sione got separated from his crew in the blackout and waited at the red bollard, the pier’s meeting spot.',k:'knows a ferry crew member',l:'I sat on that bollard for an hour. Felt like a lighthouse.',x:'My cousin is the ferry’s deckhand. His last text: “Can’t say yet. Someone needs us.”',j:'Someone needs us.',m:'Who?',h:'landmark'},
{n:'Captain Riku',r:'pier master',t:'All boats in',s:'Captain Riku runs Pier One. He won’t leave until every boat is tied and every crew is counted.',k:'knows what the tide board says',l:'Forty boats in, forty crews home. The pier sleeps now.',j:'Last one at Pier One.',m:'And the tide board.',h:'verify'}]},
{title:'Noodles on the Steps',arc:'The Canal Steps noodle stalls stay open all night for the harbor workers. Tonight the canal rose and the stall families scattered.',levels:[
{n:'Grandma Pham',r:'noodle cook',t:'The smoking wok',s:'Grandma Pham runs the oldest noodle stall on the steps. Her gas burner flared, and she walked her grandchildren out of the smoke.',k:'heard the ferry horn from the steps',l:'Sixty years cooking on these steps. Tonight I let the soup burn.',x:'Three short blasts from the fog, then nothing. I’ve heard that horn every Friday for twenty years.',j:'Three blasts.',m:'Going backwards.',h:'smoke'},
{n:'Tomo',r:'delivery cook',t:'The sign wire',s:'Tomo cooks and delivers for his family’s stall. A neon noodle sign fell, and its wire is hanging across the steps.',k:'delivered food to the ferry',l:'I deliver hot noodles. I don’t deliver myself to a live wire.',x:'I delivered noodles to the ferry crew before they left. The captain ordered extra broth “for a mother.”',j:'For a mother.',m:'There was a mother on the ferry.',h:'cable'},
{n:'Ishani',r:'tea seller',t:'The canal rising',s:'Ishani sells tea at the bottom of the steps. When the canal rose, she carried her kettle to the top step and waited.',k:'saw the ferry’s passenger list',l:'Tea can be reheated. People can’t be replaced.',x:'My cousin works the ticket booth. The passenger list had one woman marked “due any day.”',j:'Due any day.',m:'A baby.',h:'water'},
{n:'Wei',r:'student',t:'The fake closure',s:'Wei, 15, got a message saying the canal bridge had reopened. He asked the bridge guard before crossing and stayed put.',k:'knows who sent the closure messages',l:'The bridge was under water. The message said it was open. I trust my eyes.',x:'The fake messages came from a cargo company that wanted the clinic road kept clear for its trucks.',j:'They wanted the road for trucks.',m:'Not for a baby.',h:'radio'},
{n:'Auntie Rosa',r:'stall owner',t:'The cash box',s:'Auntie Rosa refused to give her payment terminal PIN to a man claiming to be from the bank during the blackout.',k:'met the ferry’s nurse',l:'I didn’t survive forty years of night markets to be robbed by a phone call.',x:'The ferry’s nurse eats at my stall. She said, “This trip, I’m carrying someone precious.”',j:'Someone precious.',m:'The mother and baby.',h:'code'},
{n:'Dr. Chen',r:'retired doctor',t:'The diabetic’s box',s:'Dr. Chen, a retired doctor who eats on the steps, sealed a diabetic stall-keeper’s insulin in a cooler for the clinic.',k:'heard the ferry call for him',l:'Retired doctors never really retire. They just eat noodles between patients.',x:'My radio picked up the ferry: “Any doctor at the clinic? We have a mother in labor.”',j:'In labor. On the ferry.',m:'That’s why they turned to the clinic.',h:'medicine',sup:1},
{n:'Kim',r:'student',t:'The floating sandal',s:'Kim, 8, lost a sandal in the canal and stayed on the steps instead of wading after it.',k:'saw a light on the water',l:'My sandal went on an adventure. I stayed home.',x:'I saw a boat light going slow, slow, toward the clinic side. Like it was carrying something fragile.',j:'Carrying something fragile.',m:'Someone fragile.',h:'gate'},
{n:'Hamid',r:'water-taxi driver',t:'The flooded underpass',s:'Hamid could have pushed his water taxi under the flooded canal bridge. He moored and waited for the water to drop.',k:'knows why the ferry went slow',l:'Fast is easy. Slow is what keeps people alive.',x:'A ferry goes slow for one reason: someone on board can’t be shaken.',j:'A woman in labor.',m:'So they went slow. And quiet.',h:'crossing'},
{n:'Nam',r:'stall cook',t:'The paper lantern',s:'Nam got lost in the fog behind the stalls and waited under the big red paper lantern where the families always meet.',k:'heard who answered the ferry',l:'The lantern was the only light on the steps. It was enough.',x:'Someone answered the ferry at last: “The clinic is open. Come to East Wharf.” A woman’s voice.',j:'The clinic answered.',m:'Mom’s old clinic.',h:'landmark'},
{n:'Old Huang',r:'stall elder',t:'Last bowl',s:'Old Huang has cooked on the Canal Steps for fifty years. He won’t close until every stall family is safe.',k:'knows what the vendors heard',l:'Fifty years of last bowls. Tonight’s was the best.',j:'Last one at the Canal Steps.',m:'And the horn.',h:'verify'}]},
{title:'Tomorrow’s Ticket',arc:'The Night Market was at its busiest when the blackout hit. Stall-holders, buskers and shoppers sheltered under the tarps.',levels:[
{n:'Leilani',r:'grill vendor',t:'The skewer fire',s:'Leilani’s grill flared when the generator failed. She cleared the crowd and is waiting at the market’s upwind end.',k:'found something strange in her tip jar',l:'I sell skewers, not fireworks. Tonight was too exciting.',x:'In my tip jar: a ferry ticket stamped with tomorrow’s date. Someone bought a return trip.',j:'A return trip.',m:'Someone planned to come home.',h:'smoke'},
{n:'Vikram',r:'phone repairer',t:'The tangled cables',s:'Vikram fixes phones at the Night Market. A string of market lights came down, and its live cable is across the aisle.',k:'repaired the ferry captain’s radio',l:'I fix tiny wires. Big wires, I leave alone.',x:'I repaired the ferry captain’s radio last week. She said, “I need it working for a very important call.”',j:'She knew the call was coming.',m:'She planned for it.',h:'cable'},
{n:'Yui',r:'busker',t:'Under the tarp',s:'Yui, a busker, is sheltering under the market tarp with her guitar while rainwater floods the main aisle.',k:'wrote a song about the ferry',l:'I sing for coins. Tonight I sang for the crowd so they’d stay calm.',x:'I wrote a song about the ferry’s three blasts. Everyone at the market knows the tune now.',j:'Three blasts.',m:'The harbor’s new song.',h:'water'},
{n:'Faisal',r:'market guard',t:'The fake evacuation',s:'Faisal got an order to clear the market toward Cargo Lane. He checked with the market office and kept everyone under cover.',k:'saw who wanted the market cleared',l:'Cargo Lane was flooding. The order didn’t add up.',x:'The cargo company wanted crowds out of the way so their trucks could use the clinic road.',j:'Trucks over people.',m:'Not tonight.',h:'radio'},
{n:'Mrs. Okafor',r:'fabric seller',t:'The lockbox',s:'Mrs. Okafor refused to give her shop’s alarm code to a caller claiming to be the market’s security company.',k:'sold a baby blanket to the ferry nurse',l:'My fabric has dressed three generations. No stranger gets my code.',x:'Last week the ferry nurse bought a tiny yellow blanket. She said, “For a passenger who isn’t born yet.”',j:'A passenger not born yet.',m:'Born on the ferry?',h:'code'},
{n:'Tavita',r:'pharmacist',t:'The market pharmacy',s:'Tavita runs the Night Market pharmacy. She sealed the asthma and allergy medicines for the clinic.',k:'filled a prescription for the ferry',l:'Medicines are promises in bottles. I keep them sealed.',x:'The ferry nurse filled a prescription here for a mother: “Due this week. Traveling home.”',j:'Traveling home to the harbor.',m:'And the harbor wouldn’t let her dock.',h:'medicine',sup:1},
{n:'Kiri',r:'student',t:'The goldfish stall',s:'Kiri, 10, saw a goldfish bag slide into the market fountain. She stayed behind the rope and called the stall owner.',k:'saw the ferry from the rooftop',l:'The goldfish is happier in the fountain anyway.',x:'From the rooftop I saw the ferry go dark and drift toward the clinic. On purpose.',j:'Lights off. Quiet.',m:'So the cargo company wouldn’t stop them.',h:'gate'},
{n:'Javier',r:'scooter courier',t:'The flooded ramp',s:'Javier could have ridden his scooter through the flooded market ramp. He parked it and waited at the top.',k:'delivered something to the clinic tonight',l:'My scooter is fast. Fast is useless if you’re under water.',x:'An hour ago I delivered a box marked “newborn kit” to the harbor clinic. Rush order.',j:'A newborn kit.',m:'The clinic knew the baby was coming.',h:'crossing'},
{n:'Ngozi',r:'shopper',t:'The giant noodle sign',s:'Ngozi got separated from her sister in the crowd and waited under the giant spinning noodle sign, their meeting spot.',k:'saw the ticket stub’s name',l:'I told my sister: if we lose each other, meet at the noodle. She found me.',x:'The ticket stub has a name in pen: “Amaya + 1.”',j:'Amaya plus one.',m:'Plus a baby.',h:'landmark'},
{n:'Madame Lao',r:'market chief',t:'Lights back on',s:'Madame Lao runs the Night Market. She won’t leave until every stall is shut and every vendor is counted.',k:'knows whose ticket was found',l:'Three hundred stalls, three hundred families. All home.',j:'Last one at the Night Market.',m:'And the ticket.',h:'verify'}]},
{title:'The Gate Crew',arc:'The Ferry Gate staff run tickets, ramps and cameras for the whole harbor. The lockdown trapped them in the terminal.',levels:[
{n:'Renzo',r:'ticket agent',t:'The smoking printer',s:'Renzo, a ticket agent, cleared the terminal when an overheated ticket printer smoked. He’s waiting on the outside ramp.',k:'sold the ferry its last tickets',l:'I print tickets. Tonight I printed an exit plan instead.',x:'I sold the last ferry eleven tickets. One passenger asked for a seat “close to the nurse.”',j:'Close to the nurse.',m:'She knew she might need one.',h:'smoke'},
{n:'Suki',r:'camera operator',t:'The camera mast',s:'Suki runs the gate cameras. The mast cable snapped and is hanging over the staff exit.',k:'has the camera footage of the ferry',l:'I watch the harbor all night. Tonight the harbor watched me.',x:'My footage shows the ferry turning away from the dock, toward the clinic side of the bay.',j:'The clinic side again.',m:'Everything points to the clinic.',h:'cable'},
{n:'Ebo',r:'ramp operator',t:'The ramp under water',s:'Ebo runs the car ramp. Storm surge flooded its bottom half, so he climbed to the control booth.',k:'got an order not to lower the ramp',l:'Ramps go down for ferries. Tonight the sea came up instead.',x:'I got an order: “Do not lower the ramp for the last ferry.” No name on it.',j:'Someone blocked the ferry on purpose.',m:'The cargo company.',h:'tide'},
{n:'Nadine',r:'terminal announcer',t:'The fake announcement',s:'Nadine got a script telling passengers to wait at Cargo Lane. She called her supervisor first and refused to read it.',k:'heard who wrote the fake script',l:'My voice tells people where to go. I won’t send them into a flood.',x:'The script came from the cargo company’s office. They wanted the terminal empty.',j:'Empty terminal, empty dock.',m:'So the ferry had nowhere to land.',h:'radio'},
{n:'Raj',r:'IT technician',t:'The ticket server',s:'Raj refused to give the ticket server’s admin password to someone claiming to be the ferry company’s head office.',k:'found a deleted message',l:'That server holds every passenger’s name. It stays locked.',x:'Someone deleted the ferry’s docking request. I recovered it: “Mother in labor. Need clinic.”',j:'They deleted it.',m:'And the ferry docked anyway.',h:'code'},
{n:'Rukhsana',r:'terminal nurse',t:'The maternity kit',s:'Rukhsana, the terminal nurse, sealed the terminal’s emergency birthing kit for the harbor clinic.',k:'trained the ferry’s nurse',l:'I’ve delivered four babies in this terminal. This kit is for the fifth.',x:'The ferry’s nurse trained with me. If anyone can deliver a baby in a storm, she can.',j:'A baby born in the storm.',m:'And the ferry crew protected her.',h:'medicine',sup:1},
{n:'Ali',r:'student',t:'The ferry pool',s:'Ali, 11, dropped his toy ferry in the terminal’s flooded fountain pool and stayed behind the barrier.',k:'saw the ferry from the window',l:'My toy ferry sank. The real one didn’t.',x:'From the window I saw the ferry’s cabin lights flash: on, off, on. Like a heartbeat.',j:'A heartbeat.',m:'A new one.',h:'gate'},
{n:'Sunita',r:'bus driver',t:'The shuttle road',s:'Sunita, the terminal shuttle driver, could have driven through the flooded shuttle road. She stopped and waited.',k:'drove the ferry’s passengers to the dock',l:'Twenty years driving this shuttle. Tonight I parked it.',x:'I drove the ferry’s passengers to the dock. One was a young mother humming to her belly.',j:'Humming.',m:'Mom used to hum to us.',h:'crossing'},
{n:'Marco',r:'luggage handler',t:'The yellow clock',s:'Marco got lost in the dark baggage hall and waited under the yellow terminal clock, the staff meeting point.',k:'carried the mother’s bag',l:'I carry bags all day. Tonight someone carried me home.',x:'I carried her bag aboard. The tag said “Amaya. Going home to have my daughter.”',j:'A daughter.',m:'Going home.',h:'landmark'},
{n:'Captain Soraya',r:'terminal manager',t:'Terminal closed',s:'Captain Soraya runs the Ferry Gate. She won’t leave until every staff member and passenger is safe.',k:'kept the camera footage safe',l:'Every ticket, every ramp, every name. Now we close.',j:'Last one at the Ferry Gate.',m:'And the footage.',h:'verify'}]},
{title:'The Crane Operators',arc:'The Crane Yard runs all night, loading container ships. When the lockdown hit, its operators were stuck high in the cabs and down on the docks.',levels:[
{n:'Kwesi',r:'crane operator',t:'The crane cab',s:'Kwesi, a crane operator, climbed down from his cab when an electrical fire smoked inside. He’s waiting at the crane’s base.',k:'heard the ferry on the crane radio',l:'Forty meters up, smoke everywhere. I climbed down slow. Slow is how you make it.',x:'On the crane radio: the ferry captain, calm: “We need a doctor. Any doctor.”',j:'She asked for a doctor.',m:'And the crane yard heard.',h:'smoke'},
{n:'Hina',r:'signal operator',t:'The signal cable',s:'Hina signals the cranes from the ground. The yard’s power cable fell across her path to the office.',k:'relayed the ferry’s call',l:'I tell cranes when to stop. Tonight I told myself.',x:'I relayed the ferry’s call to every channel. The clinic answered first.',j:'The clinic answered.',m:'Of course it did.',h:'cable'},
{n:'Tevita',r:'lasher',t:'The flooded quay',s:'Tevita secures containers on the quay. Storm surge washed over it, so he climbed onto a stack of empty containers.',k:'saw the ferry pass the yard',l:'I tie down containers. Tonight I tied myself to good sense.',x:'The ferry passed the yard with no lights, except a small lamp in the cabin. Someone was working by it.',j:'Working by lamplight.',m:'Delivering a baby by lamplight.',h:'tide'},
{n:'Isabel',r:'yard planner',t:'The fake priority',s:'Isabel got an order to send every crane to unload one company’s ship and block the clinic dock. She refused without a signed order.',k:'knows who blocked the clinic dock',l:'Cranes move cargo. They don’t block mothers.',x:'The cargo company paid to block the clinic dock with their ship. The ferry had to find another way in.',j:'So they used East Wharf.',m:'The old wharf.',h:'radio'},
{n:'Oyelaran',r:'yard supervisor',t:'The gate code',s:'Oyelaran refused to give the yard gate code to a man claiming to be a cargo inspector during the storm.',k:'saw the cargo company’s plan',l:'This gate protects four hundred workers. It stays shut.',x:'The inspector’s papers showed a plan: close the harbor clinic and build a cargo terminal there.',j:'Close the clinic.',m:'Mom’s clinic. Never.',h:'code'},
{n:'Dr. Malik',r:'yard doctor',t:'The yard’s medicines',s:'Dr. Malik, the yard’s doctor, sealed the dock workers’ heart and asthma medicines for the harbor clinic.',k:'answered the ferry’s call',l:'Twenty years treating dockers. Tonight I got a call I’ll never forget.',x:'I answered the ferry: “I’m a doctor. Go to the clinic. I’ll meet you there.” I couldn’t get there.',j:'He couldn’t get there.',m:'Then we bring him.',h:'medicine',sup:1},
{n:'Ama',r:'student',t:'The dock basin',s:'Ama, 12, visiting her dad at work, stayed behind the safety rail when her phone fell into the dock basin.',k:'heard a baby on the radio',l:'Dad says phones are replaceable. I’m not.',x:'On Dad’s radio, very faintly, I heard a baby crying. Then cheering.',j:'A baby cried.',m:'She was born.',h:'gate'},
{n:'Rangi',r:'straddle-carrier driver',t:'The flooded lane',s:'Rangi could have driven his straddle carrier through the flooded container lane. He parked it and waited.',k:'saw where the ferry headed',l:'This machine is huge. The sea is bigger.',x:'The ferry headed past the Lighthouse toward East Wharf. The lighthouse beam followed it the whole way.',j:'The lighthouse guided it.',m:'Someone at the lighthouse knew.',h:'crossing'},
{n:'Mehmet',r:'crane mechanic',t:'The blue container',s:'Mehmet got lost between container stacks and waited by the blue painted container, the yard’s landmark.',k:'heard the ferry crew cheer',l:'Every container looks the same at night. Except the blue one.',x:'Over the radio, the ferry crew cheered. The captain said: “Seven pounds. Heading for the wharf.”',j:'Seven pounds.',m:'A baby girl.',h:'landmark'},
{n:'Chief Adaeze',r:'crane chief',t:'Cranes down',s:'Chief Adaeze runs the Crane Yard. She won’t leave until every crane is locked and every operator is down.',k:'heard the ferry’s radio call',l:'Forty cranes, a hundred workers. All safe. Now I rest.',j:'Last one at the Crane Yard.',m:'And the radio call.',h:'verify'}]},
{title:'Arcade Kids',arc:'The Blue Arcade is where the harbor’s teenagers hang out after school. The blackout trapped them inside with the arcade staff.',levels:[
{n:'Jae',r:'student',t:'The smoking machine',s:'Jae, 16, smelled smoke from an old racing machine and got everyone out of the arcade’s back room.',k:'found a jacket by the door',l:'I was going for the high score. I got everyone out instead.',x:'By the arcade door: a ferry crew jacket, soaked in salt water. Someone ran here from the sea.',j:'From the ferry.',m:'Why come to the arcade?',h:'smoke'},
{n:'Hae-won',r:'student',t:'The neon wire',s:'Hae-won, 14, is waiting with her friends behind a neon sign wire that fell across the arcade entrance.',k:'saw the ferry crew member',l:'Neon looks cool until it’s on the ground and buzzing.',x:'A ferry deckhand ran in, dripping, and asked to use our phone to call the clinic.',j:'The landlines were down.',m:'But the arcade phone worked.',h:'cable'},
{n:'Bayani',r:'arcade manager',t:'The flooded basement',s:'Bayani, the arcade manager, moved everyone upstairs when water flooded the basement game room.',k:'let the deckhand use the phone',l:'I run an arcade. Tonight I ran a shelter.',x:'The deckhand called the clinic: “We’re coming in at East Wharf. Mother and baby. Please be ready.”',j:'Mother and baby.',m:'The baby was born on the ferry.',h:'water'},
{n:'Mina',r:'student',t:'The fake tournament',s:'Mina, 15, got a message about a prize tournament at Cargo Lane. She checked with her mom first and stayed put.',k:'knows who sent the tournament message',l:'Free prizes in a flood? Nice try.',x:'The cargo company sent fake events to draw people away from the clinic road.',j:'They wanted the roads empty.',m:'So their trucks could pass.',h:'radio'},
{n:'Tariq',r:'student',t:'The game account',s:'Tariq, 13, refused to share his game login with someone promising free coins during the blackout.',k:'saw the deckhand’s photo',l:'My account, my coins, my password. Simple.',x:'The deckhand showed us a photo: a tiny baby wrapped in a yellow blanket. Everyone went quiet.',j:'A yellow blanket.',m:'From the Night Market.',h:'code'},
{n:'Nurse Zara',r:'school nurse',t:'The arcade first aid',s:'Nurse Zara was picking up her son. She sealed the arcade’s first-aid kit for the harbor clinic.',k:'treated the deckhand’s hands',l:'Teenagers, blackout, broken glass. My night off went fast.',x:'The deckhand’s hands were rope-burned. He’d pulled the ferry into the wharf by hand.',j:'By hand?',m:'The cranes were blocked.',h:'medicine',sup:1},
{n:'Kojo',r:'student',t:'The canal railing',s:'Kojo, 12, dropped his game controller over the canal railing and stayed behind it.',k:'followed the deckhand outside',l:'Controllers are cheap. Canals are deep.',x:'I watched the deckhand run back toward East Wharf, carrying a bag of towels.',j:'Towels for the baby.',m:'The whole harbor helped.',h:'gate'},
{n:'Lucia',r:'student',t:'The underpass',s:'Lucia, 16, could have run through the flooded underpass to get home. She waited at the arcade for her dad.',k:'heard the deckhand’s story',l:'I wanted to go home. I wanted to get there more.',x:'The deckhand said the captain refused to leave the baby. “We dock where the baby is safe.”',j:'Where the baby is safe.',m:'The clinic.',h:'crossing'},
{n:'Farhan',r:'student',t:'The giant claw machine',s:'Farhan, 14, got separated from his brother in the dark and waited by the giant claw machine, their meeting spot.',k:'heard what the baby was named',l:'The claw machine never gave me anything. Tonight it gave me a meeting place.',x:'The deckhand said the mother named her “Marea.” It means tide.',j:'Marea, the tide baby.',m:'The lighthouse will tell that story forever.',h:'landmark'},
{n:'Old Sato',r:'arcade owner',t:'Game over',s:'Old Sato has owned the Blue Arcade for forty years. He won’t leave until every kid has gone home with family.',k:'kept the crew jacket safe',l:'Forty years of high scores. Tonight’s the best one.',j:'Last one at the Blue Arcade.',m:'And the jacket.',h:'verify'}]},
{title:'The Couriers',arc:'Cargo Lane is where the harbor’s delivery riders gather between runs. Tonight the lane flooded and the couriers were stranded.',levels:[
{n:'Ravi',r:'courier',t:'The burning scooter',s:'Ravi’s scooter battery smoked in the rain. He moved everyone away and is waiting at the end of Cargo Lane.',k:'found a box at the wrong pier',l:'My scooter’s gone. My hands and feet are fine.',x:'At Pier Three I found the ferry’s medical kit. Someone delivered it to the wrong pier on purpose.',j:'On purpose?',m:'The cargo company.',h:'smoke'},
{n:'Aiko',r:'courier',t:'The fallen line',s:'Aiko, a bicycle courier, is stuck behind a power line that fell across Cargo Lane.',k:'carried the medical kit',l:'I deliver anything. Tonight I delivered good sense.',x:'I picked up the medical kit and rode it toward East Wharf, but the lane flooded.',j:'The kit never arrived.',m:'Then the clinic needs it.',h:'cable'},
{n:'Bongani',r:'van driver',t:'The water rising',s:'Bongani’s van stalled in rising water. He climbed onto a loading dock and is waiting with his radio.',k:'saw the cargo trucks',l:'The van floats. I prefer the dock.',x:'Cargo trucks were trying to push through the lane to the clinic road. The water stopped them.',j:'The sea took the clinic’s side.',m:'The sea and us.',h:'water'},
{n:'Esra',r:'dispatcher',t:'The fake orders',s:'Esra got orders to send every courier to the cargo terminal. She called the riders back and told them to wait.',k:'knows who faked the orders',l:'My riders don’t ride into floods. Not on my watch.',x:'The cargo company faked the orders to keep couriers away from the clinic.',j:'They didn’t want the clinic to have supplies.',m:'So they’d close it.',h:'radio'},
{n:'Kai Lun',r:'courier',t:'The app login',s:'Kai Lun refused to give his courier app login to a caller claiming to be the company.',k:'saw a delivery address',l:'My account has my whole life in it. It stays mine.',x:'A delivery address on my app: “Harbor clinic. Room 3. For Amaya and baby.”',j:'Room 3.',m:'Mom’s old room.',h:'code'},
{n:'Sister Grace',r:'clinic volunteer',t:'The ferry’s kit',s:'Sister Grace volunteers at the harbor clinic. She sealed the ferry’s lost medical kit so it could finally reach the clinic.',k:'knows what was in the ferry’s kit',l:'Every package on this lane has a story. This one has a baby.',x:'The kit had baby formula, warm blankets, and a note: “For the passenger due soon.”',j:'For the passenger due soon.',m:'Amaya.',h:'medicine',sup:1},
{n:'Malakai',r:'student',t:'The storm drain',s:'Malakai, 10, saw his ball roll into a roaring storm drain and stayed back from the grate.',k:'saw the ferry from the bridge',l:'Ball’s gone. I’m here. That’s fine.',x:'From the bridge I saw the ferry pass under the lighthouse beam, really slow, like a cradle.',j:'Like a cradle.',m:'Rocking a baby.',h:'gate'},
{n:'Paulina',r:'courier',t:'The flooded bridge',s:'Paulina could have pushed her motorbike across the flooded cargo bridge. She turned back and waited.',k:'saw the clinic lights come on',l:'I lose money waiting. I don’t lose my life.',x:'Across the bay, every light in the harbor clinic came on at once. Like it was waking up.',j:'The clinic woke up.',m:'For the baby.',h:'crossing'},
{n:'Femi',r:'courier',t:'The courier bench',s:'Femi got lost in the blackout and waited at the green courier bench, where riders always meet.',k:'heard the clinic radio',l:'The bench has heard every courier story. Now it’s heard mine.',x:'The clinic radio: “Room three is ready. The baby can come home.”',j:'Room three.',m:'Mom’s room.',h:'landmark'},
{n:'Big Tunde',r:'courier boss',t:'Last delivery',s:'Big Tunde runs the courier crew. He won’t leave Cargo Lane until every rider is accounted for.',k:'knows where the kit was found',l:'Fifty riders, fifty phones, fifty safe. Last delivery done.',j:'Last one on Cargo Lane.',m:'And the kit.',h:'verify'}]},
{title:'The Lighthouse Family',arc:'The Lighthouse has been kept by the same family for four generations. Tonight they kept the beam on for a slow boat.',levels:[
{n:'Grandpa Tavi',r:'retired keeper',t:'The lamp room',s:'Grandpa Tavi, the retired keeper, climbed down from the lamp room when its old wiring smoked.',k:'kept the beam on all night',l:'Sixty years keeping this light. Tonight I nearly burned it.',x:'I kept the beam on the ferry all night. My daughter told me: “Don’t let it out of the light.”',j:'Don’t let it out of the light.',m:'They were protecting the ferry.',h:'smoke'},
{n:'Moana-Rose',r:'keeper’s daughter',t:'The lamp cable',s:'Moana-Rose, the keeper’s daughter, is stuck below the tower after the lamp’s power cable fell.',k:'talked to the ferry captain',l:'My family keeps this light. Tonight it kept us.',x:'The ferry captain radioed us: “Keep the light on. We’re carrying a newborn.”',j:'A newborn.',m:'The lighthouse knew.',h:'cable'},
{n:'Ari Tane',r:'keeper',t:'The rocks',s:'Ari Tane, the current keeper, waited on the lighthouse steps when storm surge washed over the rocks below.',k:'guided the ferry with the beam',l:'The beam is for ships. Tonight it was for one baby.',x:'I moved the beam slowly across the bay, showing the ferry the safe way to East Wharf.',j:'The safe way.',m:'Around the cargo ship.',h:'tide'},
{n:'Hemi',r:'keeper’s son',t:'The fake order',s:'Hemi, 17, got an order to switch off the lighthouse for “maintenance.” He asked his grandfather first and kept it on.',k:'knows who ordered the light off',l:'Grandpa says the light never goes off. Not ever.',x:'The order came from the cargo company. They wanted the ferry lost in the dark.',j:'They wanted it lost.',m:'The light said no.',h:'radio'},
{n:'Aroha',r:'keeper’s wife',t:'The beam control',s:'Aroha refused to give the lighthouse control password to a man claiming to be the harbor authority.',k:'saw the ferry dock',l:'This light has four generations of my family in it. Nobody touches it.',x:'Through the telescope I saw the ferry tie up at East Wharf. Very quietly.',j:'Quietly.',m:'Someone was asleep.',h:'code'},
{n:'Nurse Mere',r:'island nurse',t:'The lighthouse kit',s:'Nurse Mere, who serves the harbor islands, sealed the lighthouse’s medical kit for the clinic.',k:'spoke to the ferry’s nurse',l:'I serve twelve islands. Tonight I served one baby.',x:'The ferry nurse radioed me: “Baby girl. Healthy. Mother tired but smiling.”',j:'Healthy.',m:'And smiling.',h:'medicine',sup:1},
{n:'Pita',r:'student',t:'The tide pools',s:'Pita, 7, the keeper’s grandson, stayed behind the fence when the tide pools filled with storm water.',k:'waved at the ferry',l:'I waved my flashlight at the ferry. It waved back!',x:'The ferry flashed its light three times at the lighthouse. Grandpa says that means “thank you.”',j:'Thank you.',m:'To the light.',h:'gate'},
{n:'Wiremu',r:'boatman',t:'The causeway',s:'Wiremu could have driven across the flooded lighthouse causeway. He waited on the lighthouse side.',k:'saw the clinic waiting',l:'The causeway will be there tomorrow. So will I.',x:'On East Wharf, people were waiting with lanterns. The clinic sent its night shift to the dock.',j:'The whole clinic.',m:'Mom would be proud.',h:'crossing'},
{n:'Kahu',r:'keeper’s cousin',t:'The white post',s:'Kahu got lost in the fog and waited by the white lighthouse post, the family’s meeting spot.',k:'heard the baby’s name',l:'The post has stood here a hundred years. I stood here one night.',x:'The ferry nurse said the baby is named Marea. Because she was born on the tide.',j:'The lighthouse heard her name first.',m:'Grandpa will tell that story forever.',h:'landmark'},
{n:'Nana Huia',r:'family elder',t:'The light stays on',s:'Nana Huia, the oldest of the lighthouse family, refused to leave until all four generations were safe.',k:'knows what the beam guided',l:'Four generations. One light. Everyone home.',j:'Last one at the Lighthouse.',m:'And the beam.',h:'verify'}]},
{title:'The Night Shift',arc:'The harbor clinic’s night shift went down to East Wharf to meet the ferry. Then the storm cut them off from the clinic.',levels:[
{n:'Dr. Ayesha',r:'clinic doctor',t:'The wharf shed',s:'Dr. Ayesha led the night shift out of the wharf shed when its heater smoked.',k:'delivered the baby’s first checkup',l:'Healthy baby, tired mother, wet doctor. Good night.',x:'The moorings at East Wharf were freshly tied. The ferry docked an hour ago, in the dark.',j:'They docked.',m:'They made it.',h:'smoke'},
{n:'Nurse Lani',r:'night nurse',t:'The wharf line',s:'Nurse Lani is waiting with the baby’s blankets behind a power line that fell across the wharf.',k:'held the baby first',l:'I’ve held a thousand babies. This one held me.',x:'The baby has the tiniest hands. The mother says she’ll name her Marea.',j:'Marea.',m:'Like the tide.',h:'cable'},
{n:'Sefa',r:'clinic orderly',t:'The wharf ramp',s:'Sefa, the clinic orderly, carried the stretcher up to the dry warehouse when water covered the wharf ramp.',k:'carried the mother to safety',l:'I carry people for a living. Tonight I carried two at once.',x:'I carried Amaya off the ferry. She kept saying, “Thank you for staying open.”',j:'For staying open.',m:'The clinic stayed open.',h:'water'},
{n:'Dr. Felipe',r:'clinic doctor',t:'The fake transfer',s:'Dr. Felipe got an order to transfer the mother to a private hospital across town. He called the clinic chief before moving anyone.',k:'knows who ordered the transfer',l:'A tired mother and a newborn don’t cross a city in a storm.',x:'The transfer order came from the cargo company. They wanted the clinic to look useless.',j:'It’s not useless.',m:'It just saved two lives.',h:'radio'},
{n:'Admin Hana',r:'clinic administrator',t:'The patient records',s:'Admin Hana refused to give the clinic’s patient records password to someone claiming to be the health department.',k:'kept the clinic’s records safe',l:'Every patient’s secrets are safe with me.',x:'The records show the clinic had planned to close tonight. The cargo company had bought it.',j:'Bought it?',m:'Not anymore. Not after tonight.',h:'code'},
{n:'Ola',r:'clinic pharmacist',t:'The newborn medicines',s:'Ola, the clinic pharmacist, sealed the newborn’s first medicines for the trip back to the clinic.',k:'stocked the clinic for the baby',l:'Vitamin K, eye drops, and a lot of love. All sealed.',x:'Ola stocked Room 3 for the baby. The same room Mom used to work in.',j:'Room 3.',m:'Mom’s room.',h:'medicine',sup:1},
{n:'Tama',r:'student',t:'The wharf ladder',s:'Tama, 13, a nurse’s son, stayed at the top of the wharf ladder when the water rose below.',k:'saw the ferry captain',l:'Mom says the water is for boats, not boys.',x:'The ferry captain stood on deck, soaked, holding a tiny yellow bundle up to the clinic lights.',j:'She showed the baby to the harbor.',m:'Like a promise.',h:'gate'},
{n:'Paramedic Joon',r:'paramedic',t:'The wharf road',s:'Paramedic Joon could have driven the ambulance down the flooded wharf road. He waited for the water to drop.',k:'saw the ferry crew’s faces',l:'An ambulance in a flood is just a boat with sirens.',x:'The ferry crew looked exhausted and happy. They’d been awake for twenty hours.',j:'Twenty hours.',m:'For one baby.',h:'crossing'},
{n:'Nurse Elif',r:'clinic nurse',t:'The wharf crane',s:'Nurse Elif got separated in the dark and waited under the old wharf crane, the night shift’s meeting spot.',k:'heard what the captain said',l:'The crane hasn’t moved in thirty years. Neither did I.',x:'The captain said: “We turned away because the clinic was the only place that would take her.”',j:'The only place.',m:'Mom’s clinic.',h:'landmark'},
{n:'Dr. Mbeki',r:'clinic chief',t:'Shift change',s:'Dr. Mbeki, the clinic chief, won’t leave East Wharf until every patient and nurse is back inside.',k:'knows why the moorings were tied',l:'The night shift ends. The clinic stays open.',j:'Last one at East Wharf.',m:'And the moorings.',h:'verify'}]},
{title:'The Last Ferry',arc:'The last ferry’s crew turned away from the closed dock to bring a mother to the only clinic that would take her. Tonight they bring her home.',levels:[
{n:'Engineer Bae',r:'ferry engineer',t:'The engine room',s:'Engineer Bae kept the ferry’s engine running all night. When it finally smoked, he shut it down and climbed on deck.',k:'ran the engine slow for the baby',l:'I ran that engine as gently as a lullaby. It earned its rest.',x:'I ran the engine at half speed so the mother wouldn’t feel the waves. Twenty hours.',j:'Twenty hours, half speed.',m:'For one mother.',h:'smoke'},
{n:'Iosefa',r:'ferry deckhand',t:'The mooring line',s:'Iosefa, the deckhand who ran to the arcade, is stuck on deck behind a snapped mooring cable.',k:'tied the ferry up by hand',l:'I pulled that ferry in with my hands. They’re sore. They’re proud.',x:'I tied the moorings myself. The cranes were blocked, so I did it by hand.',j:'By hand.',m:'The whole crew is a hero.',h:'cable'},
{n:'Cook Pedro',r:'ferry cook',t:'The galley',s:'Cook Pedro waited in the galley when the deck flooded, keeping the broth warm for the mother.',k:'made broth for the mother',l:'I cooked for six hundred passengers. Tonight I cooked for one.',x:'I made broth for Amaya all night. The noodle stall’s recipe. She said it tasted like home.',j:'Like home.',m:'Like the Canal Steps.',h:'water'},
{n:'Navigator Iris',r:'ferry navigator',t:'The fake course',s:'Navigator Iris got a new course telling the ferry to anchor outside the harbor. She checked with the captain and refused.',k:'charted the slow course',l:'Charts are just suggestions. A baby’s safety isn’t.',x:'The cargo company sent the fake course. We charted our own, under the lighthouse beam.',j:'Under the beam.',m:'The lighthouse family helped.',h:'radio'},
{n:'Purser Leo',r:'ferry purser',t:'The ticket safe',s:'Purser Leo refused to open the ferry’s ticket safe for “port officials” who boarded at East Wharf.',k:'kept tomorrow’s ticket',l:'Passengers trust us with their tickets. And with their lives.',x:'I printed Amaya a ticket for tomorrow. A free one. So she can come home again.',j:'Tomorrow’s ticket.',m:'From the Night Market.',h:'code'},
{n:'Nurse Teresa',r:'ferry nurse',t:'The delivery kit',s:'Nurse Teresa, the ferry nurse, sealed the delivery kit she used on board for the clinic.',k:'delivered the baby on the ferry',l:'Born at sea, in a storm, by lamplight. She’ll have stories to tell.',x:'I delivered Marea at two in the morning. The whole crew held the lamp.',j:'The whole crew.',m:'Like a family.',h:'medicine',sup:1},
{n:'Ben',r:'student',t:'The deck rail',s:'Ben, 12, a passenger, stayed behind the deck rail when his cap blew off into the harbor.',k:'helped hold the lamp',l:'I held the lamp. I was scared. I didn’t drop it.',x:'I held the lamp while the nurse helped the baby out. I’ll never forget it.',j:'He was there.',m:'A hero too.',h:'gate'},
{n:'Bosun Ruth',r:'ferry bosun',t:'The flooded gangway',s:'Bosun Ruth could have rushed the passengers across the flooded gangway. She waited for the tide to fall.',k:'kept the crew calm',l:'A ferry is only as calm as its bosun. I stayed very calm.',x:'I told the crew: “We don’t dock where it’s easy. We dock where she’s safe.”',j:'Where she’s safe.',m:'That’s the harbor rule now.',h:'tide'},
{n:'Captain Ines',r:'ferry captain',t:'The ferry’s bell',s:'Captain Ines refused to leave her ferry until the mother and baby were ashore. She waited by the ferry’s brass bell.',k:'chose to turn the ferry away',l:'I turned my ferry away from a closed dock. I’d do it again tomorrow.',x:'I turned away from Ferry Gate because they wouldn’t take her. The clinic would.',j:'The clinic would.',m:'Because we kept the roads clear.',h:'landmark'},
{n:'Amaya',r:'new mother',t:'Marea',s:'Amaya, holding her newborn daughter Marea, is waiting at the Last Ferry berth for a ride to the harbor clinic.',k:'named her daughter after the tide',l:'She was born on the tide. Now she gets to grow up on land.',w:'baby Marea',j:'Welcome home, Marea.',m:'The clinic is waiting.',h:'verify'}]}
]};
